//! Header-level delivery evidence. Tags are declarations, not calibration.
use serde_json::{json,Value};use std::{process::{Command,Stdio,Child},io::Read};
struct Probe(Child);impl Drop for Probe{fn drop(&mut self){let _=self.0.kill();let _=self.0.wait();}}
pub fn inspect(path:&str)->Result<Value,String>{if path.is_empty()||path.starts_with('-')||path.contains("://"){return Err("delivery inspection requires local file path".into())}let file=std::fs::metadata(path).map_err(|e|format!("delivery stat: {e}"))?;if !file.is_file(){return Err("delivery path must be a file".into())}let mut child=Probe(Command::new("ffprobe").args(["-v","error","-show_streams","-show_format","-of","json",path]).stdout(Stdio::piped()).stderr(Stdio::null()).spawn().map_err(|e|e.to_string())?);let mut bytes=Vec::new();child.0.stdout.take().ok_or("no delivery probe output")?.take(1024*1024+1).read_to_end(&mut bytes).map_err(|e|e.to_string())?;if bytes.len()>1024*1024{return Err("delivery header exceeds1MiB".into())}if !child.0.wait().map_err(|e|e.to_string())?.success(){return Err("delivery header probe failed".into())}let raw:Value=serde_json::from_slice(&bytes).map_err(|e|e.to_string())?;let mut streams=Vec::new();for s in raw["streams"].as_array().ok_or("no delivery streams")?{let mut out=serde_json::Map::new();for k in ["index","codec_type","codec_name","pix_fmt","width","height","color_range","color_space","color_transfer","color_primaries","bits_per_raw_sample","nb_frames","r_frame_rate","duration","sample_rate","channels","side_data_list"]{if let Some(v)=s.get(k){out.insert(k.into(),v.clone());}}streams.push(Value::Object(out));}
 let missing:Vec<_>=streams.iter().filter(|s|s["codec_type"]=="video").map(|s|{let keys:Vec<_>=["color_primaries","color_transfer","color_space","color_range"].iter().filter(|k|s.get(**k).is_none()||s[**k]=="unknown"||s[**k]=="unspecified").copied().collect();json!({"stream_index":s["index"],"absent_or_unspecified_color_fields":keys})}).collect();Ok(json!({"path":path,"bytes":file.len(),"container":raw["format"]["format_name"],"declared_duration":raw["format"]["duration"],"streams":streams,"tag_gaps":missing,"inspection":"header-only, no frame decode/count or color inference","note":"Container/codec tags and static side data are file-declared. Missing tags do not prove wrong pixels; present tags do not prove matching pixels, calibrated mastering, HDR compliance or display quality. No project settings changed."}))}
